import{$,notify}from'../../project-kit.js';import{operations,password}from'./operations.js';let tab='json',countFrame=0;
function counts(){if(countFrame)return;countFrame=requestAnimationFrame(()=>{countFrame=0;const s=$('#input').value;let words=0,lines=s?1:0,inWord=false;for(let i=0;i<s.length;i++){const char=s[i];if(/\s/.test(char)){if(char==='\n')lines++;inWord=false}else if(!inWord){words++;inWord=true}}$('#counts').textContent=`${s.length.toLocaleString()} characters · ${words} words · ${lines} lines`})}
function tabs(){document.querySelectorAll('[data-tab]').forEach(b=>{const active=b.dataset.tab===tab;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active))});$('#text-tools').hidden=tab==='password';$('#password-tools').hidden=tab!=='password';$('#input').placeholder=tab==='json'?'Paste JSON here…':tab==='encoding'?'Text to encode or decode…':'Paste text here…';$('#operations').replaceChildren();for(const[name,operation]of Object.entries(operations[tab]||{})){const b=document.createElement('button');b.className='secondary';b.textContent=name;b.onclick=()=>{try{$('#output').value=operation($('#input').value);$('#tool-status').textContent='Done · '+name}catch(e){$('#output').value='';$('#tool-status').textContent='Could not complete '+name+': '+e.message}};$('#operations').append(b)}$('#tool-status').textContent=''}document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;tabs()});$('#input').oninput=counts;$('#clear-input').onclick=()=>{$('#input').value=$('#output').value='';counts();$('#tool-status').textContent='Cleared'};$('#use-output').onclick=()=>{$('#input').value=$('#output').value;counts()};async function copy(value){if(!value){notify('Nothing to copy yet.');return}try{await navigator.clipboard.writeText(value);notify('Copied')}catch{notify('Copy unavailable. Select and copy the text manually.')}}$('#copy-output').onclick=()=>copy($('#output').value);$('#generate').onclick=()=>{try{$('#password').textContent=password(Number($('#length').value),{symbols:$('#symbols').checked,avoid:$('#ambiguous').checked});$('#tool-status').textContent='Generated locally. Not saved.'}catch(e){$('#password').textContent='';$('#tool-status').textContent=e.message}};$('#copy-password').onclick=()=>copy($('#password').textContent);$('#clear-password').onclick=()=>{$('#password').textContent='';$('#tool-status').textContent='Password cleared from this page.'};counts();tabs();
